<template>
  <view class="page">
    <!-- 返回按钮 -->
    <navigator url="/pages/index/index" class="back-btn">
    </navigator>

    <!-- 表单容器 -->
    <view class="form-container">
      <!-- 服务日期 -->
      <view class="form-item">
        <text class="label">服务日期 *</text>
        <picker mode="date" :value="serviceDate" @change="onDateChange" class="input">
          <view class="input-text">
            {{ serviceDate ? serviceDate.replace(/-/g, '/') : '请选择日期' }}
          </view>
        </picker>
      </view>

      <!-- 服务时段（开始 + 结束） -->
      <view class="form-item">
        <text class="label">服务时段 *</text>
        <view class="time-range">
          <picker mode="time" :value="startTime" @change="onStartTimeChange" class="time-picker">
            <view class="input-text">{{ startTime || '开始' }}</view>
          </picker>
          <text class="dash">–</text>
          <picker mode="time" :value="endTime" @change="onEndTimeChange" class="time-picker">
            <view class="input-text">{{ endTime || '结束' }}</view>
          </picker>
        </view>
      </view>

      <!-- 医院名称 -->
      <view class="form-item">
        <text class="label">医院名称 *</text>
        <input v-model="hospitalName" placeholder="请填写医院信息" placeholder-style="color: #999;" class="input" />
      </view>

      <!-- 联系人信息 -->
      <view class="form-item">
        <text class="label">联系人信息 *</text>
        <input v-model="contactPerson" placeholder="姓名" class="input" />
        <input v-model="contactPhone" placeholder="手机号" class="input" type="number" maxlength="11" @input="contactPhone = contactPhone.replace(/\D/g, '').slice(0, 11)" />
      </view>

      <!-- 备注信息 -->
      <view class="form-item">
        <text class="label">备注信息</text>
        <textarea v-model="notes" placeholder="请输入备注" class="textarea"></textarea>
      </view>
    </view>

    <!-- 按钮区域 -->
    <view class="btn-group">
      <button class="btn-primary" @click="confirmAppointment">确认预约</button>
      <!-- <text class="skip-link" @click="skipToAICare">跳过该过程，到预约类型选择</text> -->
    </view>
  </view>
</template>

<script setup>
import { ref } from 'vue'
// 引入api.js的post请求方法（路径根据项目实际结构调整）
import { post } from '@/utils/api.js'

// 数据 - 保持原有字段
// 修改：将默认日期设置为当前日期
const getCurrentDate = () => {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0'); // getMonth() 从 0 开始，需要 +1
  const day = String(now.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

const serviceDate = ref(getCurrentDate()); // 使用函数获取当前日期
const startTime = ref('14:00');
const endTime = ref('16:00');
const hospitalName = ref('');
const contactPerson = ref('');
const contactPhone = ref('');
const notes = ref(''); // 用于备注信息

// 日期选择
const onDateChange = (e) => {
  serviceDate.value = e.detail.value;
}

// 时间选择
const onStartTimeChange = (e) => {
  startTime.value = e.detail.value;
}

const onEndTimeChange = (e) => {
  endTime.value = e.detail.value;
}

// 时间比较工具函数（HH:mm -> 分钟数）
const timeToMinutes = (timeStr) => {
  if (!timeStr) return -1;
  const [h, m] = timeStr.split(':').map(Number);
  return h * 60 + m;
}

// ✅ 手机号验证函数
const isValidPhone = (phone) => {
  const reg = /^1[3-9]\d{9}$/;
  return reg.test(phone.trim());
}

// 提交预约（改为调用api接口）
const confirmAppointment = async () => {
  // 校验必填项 - 仅校验界面上的字段
  if (
    !serviceDate.value ||
    !startTime.value ||
    !endTime.value ||
    !hospitalName.value.trim() ||
    !contactPerson.value.trim() ||
    !contactPhone.value.trim()
  ) {
    uni.showToast({
      title: '请填写必要信息',
      icon: 'none'
    });
    return;
  }

  // ✅ 校验手机号格式
  if (!isValidPhone(contactPhone.value)) {
    uni.showToast({
      title: '请输入正确的11位手机号',
      icon: 'none'
    });
    return;
  }

  // 校验时间逻辑：结束时间必须晚于开始时间
  if (timeToMinutes(endTime.value) <= timeToMinutes(startTime.value)) {
    uni.showToast({
      title: '结束时间需晚于开始时间',
      icon: 'none'
    });
    return;
  }

  // 构造接口请求参数
  const formData = {
    serviceDate: serviceDate.value,
    startTime: startTime.value,
    endTime: endTime.value,
    hospitalName: hospitalName.value.trim(),
    contactPerson: contactPerson.value.trim(),
    contactPhone: contactPhone.value.trim(),
    notes: notes.value.trim()
  };

  try {
    // 调用api.js的post方法提交预约（接口路径根据实际后端接口调整）
    const res = await post('/utils/api.js', formData);
    
    // 接口请求成功（api.js已处理code=200的判断）
    uni.showToast({
      title: '预约提交成功',
      icon: 'success'
    });

    // 从接口返回数据中获取预约号（假设后端返回appointmentNo）
    const appointmentNo = res.data.appointmentNo;
    
    // 跳转到匹配页面，传递接口返回的预约号
    setTimeout(() => {
      uni.navigateTo({
        url: `/pages/AICareMatchPage/AICareMatchPage?appointmentNo=${encodeURIComponent(appointmentNo)}`
      });
    }, 1000);
  } catch (err) {
    // 错误提示已在api.js的拦截器中自动处理，此处仅做日志记录
    console.error('预约提交失败：', err);
  }
}

// 移除skipToAICare中本地存储相关逻辑（如需保留可调整为调用接口）
const skipToAICare = async () => {
  try {
    // 调用跳过预约的接口（根据实际后端接口调整）
    const res = await post('/api/appointment/skip', {
      serviceDate: serviceDate.value,
      startTime: startTime.value,
      endTime: endTime.value
    });
    
    const tempAppointmentNo = res.data.appointmentNo;
    uni.navigateTo({
      url: `/pages/AICareMatchPage/AICareMatchPage?appointmentNo=${encodeURIComponent(tempAppointmentNo)}`
    });
  } catch (err) {
    console.error('跳过预约失败：', err);
  }
}
</script>

